  const PQ = { SKY: 92, CITY: 150, RAIL: 178 };
  function pqPathY(p, x) { const q = p.pts; for (let i = 1; i < q.length; i++) if (q[i][0] >= x) { const [x0, y0] = q[i - 1], [x1, y1] = q[i]; return lerp(y0, y1, (x - x0) / Math.max(1, x1 - x0)); } return q[q.length - 1][1]; }
