    ctx.fillStyle = gr(ctx, PQ.RAIL, H, '#9ED37B', '#79BA5A'); ctx.fillRect(x0, PQ.RAIL, w, H - PQ.RAIL);
    ctx.fillStyle = 'rgba(255,255,255,.045)'; for (let x = Math.floor(x0 / 140) * 140; x < x1; x += 140) ctx.fillRect(x, PQ.RAIL, 70, H - PQ.RAIL);
